import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"First-time setup","description":"","frontmatter":{},"headers":[],"relativePath":"setup.md","filePath":"setup.md","lastUpdated":1793024353000}'),r={name:"setup.md"};function i(n,e,p,d,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="first-time-setup" tabindex="-1">First-time setup <a class="header-anchor" href="#first-time-setup" aria-label="Permalink to &quot;First-time setup&quot;">​</a></h1><p>This page walks through the setup window that opens the first time you start MeetCue. It takes about five minutes, most of it spent creating API keys.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>You need an account with one speech recognition provider and one language model provider. MeetCue doesn&#39;t pick them for you: you choose the provider and type the model name for each task.</p><table tabindex="0"><thead><tr><th>Task</th><th>Providers in this release</th></tr></thead><tbody><tr><td>Speech recognition</td><td>Soniox, Deepgram</td></tr><tr><td>Question detection and hints</td><td>Anthropic, any OpenAI-compatible API</td></tr></tbody></table><p>Detection and hints can use different models, and even different providers. Detection is a simple yes/no task, so a cheaper model is usually enough.</p><h2 id="step-1-language" tabindex="-1">Step 1: Language <a class="header-anchor" href="#step-1-language" aria-label="Permalink to &quot;Step 1: Language&quot;">​</a></h2><p>Choose <strong>English</strong> or <strong>简体中文</strong>, or let MeetCue follow the Windows display language. You can change it later in <strong>Settings › General</strong>; every window switches immediately.</p><h2 id="step-2-audio" tabindex="-1">Step 2: Audio <a class="header-anchor" href="#step-2-audio" aria-label="Permalink to &quot;Step 2: Audio&quot;">​</a></h2><p>MeetCue listens to two sources:</p><ul><li><strong>Microphone (you)</strong>: the microphone you speak into. <em>System default</em> follows the device chosen in Windows Sound settings.</li><li><strong>Other participants</strong>: everything played through your default output device, which is how meeting apps play other people&#39;s voices.</li></ul><p>Click <strong>Test levels</strong>, play a video and say something. Both level bars should move. If the system sound bar stays flat, see <a href="/meetcue/troubleshooting/audio">Audio and devices</a>.</p><div class="tip custom-block"><p class="custom-block-title">Use headphones</p><p>With speakers, your microphone also picks up the other participants. MeetCue filters most of this echo, but headphones give the cleanest result.</p></div><h2 id="step-3-providers-and-models" tabindex="-1">Step 3: Providers and models <a class="header-anchor" href="#step-3-providers-and-models" aria-label="Permalink to &quot;Step 3: Providers and models&quot;">​</a></h2><p>For each of the three tasks, choose a <strong>Provider</strong> and type a <strong>Model</strong> name. Any name the provider accepts works, including models released after this version of MeetCue; once the provider&#39;s key is saved, the names it reports appear as suggestions while you type. You can&#39;t continue until all three tasks have a provider and a model.</p><p>MeetCue doesn&#39;t list models or prices. Each provider has an <strong>Official pricing</strong> link to its own price page; for OpenAI-compatible services, check the pricing page of the service you use.</p><p>Below the tasks, <strong>Addresses &amp; keys</strong> shows a row for each provider you chose:</p><ul><li><strong>Base URL</strong>: required for OpenAI-compatible services, for example <code>https://llm.example.com/v1</code>. For Anthropic it&#39;s optional: leave it empty to use <code>https://api.anthropic.com</code>, or enter a gateway or proxy that speaks the same API.</li><li><strong>Key</strong>: paste it and click <strong>Save and verify</strong>. MeetCue stores keys only in Windows Credential Manager; they never appear in the settings file or the logs.</li></ul><p>How to get each key is described in <a href="/meetcue/guide/providers">Providers and keys</a>:</p><ul><li><a href="/meetcue/guide/providers#soniox">Soniox</a></li><li><a href="/meetcue/guide/providers#deepgram">Deepgram</a></li><li><a href="/meetcue/guide/providers#anthropic">Anthropic</a></li><li><a href="/meetcue/guide/providers#openai-compatible-apis">OpenAI-compatible APIs</a></li></ul><p>If verification fails, the message shows an error code such as <a href="/meetcue/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>. Click <strong>See the fix</strong> to open the matching section.</p><h2 id="step-4-latency-probe" tabindex="-1">Step 4: Latency probe <a class="header-anchor" href="#step-4-latency-probe" aria-label="Permalink to &quot;Step 4: Latency probe&quot;">​</a></h2><p>The probe measures how fast each provider responds from your network and picks the fastest endpoint for each one. It costs a few cents with keys, or nothing if you only measure the network. You can skip it and run it later from <strong>Settings › Providers &amp; cost</strong>. See <a href="/meetcue/guide/latency">Latency probe</a>.</p><h2 id="step-5-done" tabindex="-1">Step 5: Done <a class="header-anchor" href="#step-5-done" aria-label="Permalink to &quot;Step 5: Done&quot;">​</a></h2><p>Press <code>Ctrl+Alt+Space</code> when your next meeting starts. To see MeetCue in action first, try the <a href="/meetcue/quick-start">five-minute tour</a>.</p><p>To test everything with your own voice before a real meeting, click <strong>Finish and try a mock interview</strong>. See <a href="/meetcue/guide/mock-interview">Mock interview</a>.</p>',26)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
